func (s *Server) adminSettings(w http.ResponseWriter, r *http.Request) {
	items, err := s.store.Settings(r.Context())
	if err != nil {
		writeStoreError(w, err)
		return
	}
	for key, raw := range items {
		var obj map[string]any
		if json.Unmarshal(raw, &obj) == nil {
